class Solution:
    def maxValue(self, n: str, x: int) -> str:
        neg = n[0] == '-'
        body = n[1:] if neg else n
        best = None
        for p in range(len(body) + 1):
            cand = body[:p] + str(x) + body[p:]
            if best is None or (cand < best if neg else cand > best):
                best = cand
        return ('-' + best) if neg else best

