class Solution {
public:
    string maxValue(string n, int x) {
        bool neg = n[0] == '-';
        string body = neg ? n.substr(1) : n;
        char xc = char('0' + x);
        string best;
        for (int p = 0; p <= (int)body.size(); ++p) {
            string cand = body.substr(0, p) + xc + body.substr(p);
            if (best.empty() || (neg ? cand < best : cand > best)) best = cand;
        }
        return neg ? "-" + best : best;
    }
};

