class Solution {
public:
    string maxValue(string n, int x) {
        char xc = char('0' + x);
        int i = 0, len = n.size();
        if (n[0] == '-') {
            i = 1;
            while (i < len && n[i] <= xc) ++i;
        } else {
            while (i < len && n[i] >= xc) ++i;
        }
        n.insert(i, 1, xc);
        return n;
    }
};

