class Solution {
    public String maxValue(String n, int x) {
        char xc = (char) ('0' + x);
        int i = 0, len = n.length();
        if (n.charAt(0) == '-') {
            i = 1;
            while (i < len && n.charAt(i) <= xc) i++;
        } else {
            while (i < len && n.charAt(i) >= xc) i++;
        }
        return n.substring(0, i) + xc + n.substring(i);
    }
}

